Matching Ayahs
- = అలిఫ్, లామ్, మీమ్. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = వారే తమ ప్రభువు నుండి సన్మార్గంలో ఉన్నవారు, మరియు వారే విజయం సాధించినవారు. 2:5; 31:5
- = ఓ ఇస్రాయీల్ సంతానమా! నేను మీకు ప్రసాదించిన నా అనుగ్రహాన్ని, మరియు నేను మిమ్మల్ని సమస్త లోకాల (ప్రజల) పైన గొప్పవారిగా చేశానని గుర్తుంచుకోండి. 2:47; 2:122
- = ఆ సమాజం గతించి పోయింది. వారు సంపాదించినది వారికి, మీరు సంపాదించినది మీకు. మరియు వారు చేస్తున్న దాని గురించి మిమ్మల్ని ప్రశ్నించరు. 2:134; 2:141
- = వారు అందులో శాశ్వతంగా ఉంటారు; వారి శిక్ష తగ్గించబడదు, మరియు వారికి వ్యవధి కూడా ఇవ్వబడదు. 2:162; 3:88
- = అయితే దీని తర్వాత పశ్చాత్తాప పడి, తమను తాము సవరించుకునేవారు మినహా. నిశ్చయంగా అల్లాహ్ క్షమించేవాడు, అపార కరుణామయుడు. 3:89; 24:5
- = మరియు ఎవరు సత్యతిరస్కారం చేశారో మరియు మా సూచనలను అబద్ధమన్నారో – వారే నరకవాసులు. 5:10; 5:86
- = మరియు వారి ప్రభువు నుండి ఏ సూచన వచ్చినా, వారు దాని నుండి ముఖం తిప్పుకుంటారు. 6:4; 36:46
- = మరియు మీకు ముందు కూడా ప్రవక్తలను అపహాస్యం చేయబడింది; కానీ అపహాస్యం చేసిన వారిని, వారు ఏది అపహాస్యం చేస్తున్నారో అదే చుట్టుముట్టింది. 6:10; 21:41
- = ఇలా చెప్పు: "నేను నా ప్రభువుకు అవిధేయత చూపిస్తే, మహా దినపు శిక్షకు భయపడతాను." 6:15; 39:13
- = అప్పుడు భూకంపం వారిని పట్టుకుంది, మరియు వారు తమ ఇళ్లలో బోర్లాపడి (చనిపోయి) ఉండిపోయారు. 7:78; 7:91
- = అప్పుడు అతను (మూసా) తన కర్రను విసిరాడు; అది అకస్మాత్తుగా ఒక స్పష్టమైన పాముగా మారింది. 7:107; 26:32
- = మరియు అతను తన చేతిని బయటికి తీశాడు; అది చూసేవారికి తెల్లగా (మెరుస్తూ) కనిపించింది. 7:108; 26:33
- = వారు అన్నారు: "మేము సమస్త లోకాల ప్రభువును విశ్వసించాము." 7:121; 26:47
- = మూసా మరియు హారూన్ ల ప్రభువు. 7:122; 26:48
- = మరియు నేను వారికి వ్యవధి ఇస్తాను. నిశ్చయంగా నా యుక్తి దృఢమైనది. 7:183; 68:45
- = ఆయనే తన ప్రవక్తను సన్మార్గంతో మరియు సత్యమతంతో పంపినవాడు – దానిని అన్ని మతాల పైన ఆధిపత్యం కలిగించడానికి, బహుదైవారాధకులు అసహ్యించుకున్నా. 9:33; 61:9
- = ఓ ప్రవక్తా! సత్యతిరస్కారులతో మరియు కపటులతో పోరాడండి, మరియు వారి పట్ల కఠినంగా ఉండండి. వారి నివాసం నరకమే; మరియు అది ఎంత చెడ్డ గమ్యస్థానం! 9:73; 66:9
- = మరియు వారు అంటారు: "మీరు సత్యవంతులైతే, ఈ వాగ్దానం ఎప్పుడు?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = మరియు నిశ్చయంగా మేము మూసాను మా సూచనలతో మరియు స్పష్టమైన అధికారంతో పంపాము. 11:96; 40:23
- = మరియు నిశ్చయంగా మేము మూసాకు గ్రంథాన్ని ఇచ్చాము; కానీ దాని విషయంలో విభేదించారు. మరియు మీ ప్రభువు నుండి ఒక మాట ముందుగా నిర్ణయించబడకపోతే, వారి మధ్య తీర్పు చేయబడి ఉండేది. మరియు నిశ్చయంగా వారు దాని గురించి సందేహంలో ఉన్నారు. 11:110; 41:45
