- = (ఇబ్లీస్) అన్నాడు: "నా ప్రభూ! అయితే వారు పునరుత్థానం చేయబడే దినం వరకు నాకు వ్యవధి ఇవ్వు." 15:36; 38:79
- = (అల్లాహ్) అన్నాడు: "అయితే నిశ్చయంగా నీవు వ్యవధి ఇవ్వబడిన వారిలో ఒకడవు." 15:37; 38:80
