- = వారు అన్నారు: "నిశ్చయంగా మేము నేరస్థులైన ప్రజల వద్దకు పంపబడ్డాము." 15:58; 51:32
- = ఎవరు విశ్వసించి, తమ విశ్వాసాన్ని అన్యాయంతో కలపరో – వారికి భద్రత ఉంది; మరియు వారే సన్మార్గంలో ఉన్నవారు. 16:42; 29:59
- = వారు మేము ఇచ్చిన దానికి కృతఘ్నులుగా మారడానికి. కాబట్టి మీరు ఆనందించండి; ఎందుకంటే మీరు త్వరలో తెలుసుకుంటారు. 16:55; 30:34
