- = అయితే వీటికి మించి కోరేవారు – వారే హద్దు మీరినవారు. 23:7; 70:31
- = మరియు వారు తమ బాధ్యతలను మరియు ఒప్పందాలను నెరవేర్చువారు. 23:8; 70:32
- = (నూహ్) అన్నాడు: "నా ప్రభూ! వారు నన్ను అబద్ధికుడన్నారు కాబట్టి నాకు సహాయం చేయి." 23:26; 23:39
