- వారు భూమిలో ప్రయాణించి, తమకు పూర్వం ఉన్నవారి ముగింపు ఎలా ఉందో చూడలేదా? (أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن) 30:9; 35:44; 40:82; 47:10
- వారికి వారి ప్రభువు వద్ద వారి ప్రతిఫలం ఉంది; వారికి భయం లేదు, వారు దుఃఖించరు. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:62; 2:262; 2:274; 2:277
- ఇంకా, ఎవరు విశ్వసించి సత్కర్మలు చేశారో, వారు స్వర్గాలలో ప్రవేశింపజేయబడతారు; వాటి క్రింద నదులు ప్రవహిస్తాయి. (وَأُدْخِلَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 14:23; 22:14; 22:23; 47:12
- ఆయన ఇలా అన్నాడు: "నా ప్రజలారా! అల్లాహ్ను ఆరాధించండి; ఆయన తప్ప మీకు వేరే దైవం లేదు. మీరు?" (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23
- వారి సంపదలూ, వారి సంతానమూ అల్లాహ్ ఎదుట వారికి ఏమాత్రం ఉపయోగపడవు; అటువంటి వారు. (لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَئِكَ) 3:10; 3:116; 58:17
- స్వర్గాలు, వాటి క్రింద నదులు ప్రవహిస్తాయి; అందులో వారు శాశ్వతంగా ఉంటారు; అదే గొప్ప విజయం. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ) 4:13; 9:89
- తమకు పూర్వం ఉన్నవారి వార్త – నూహ్, ఆద్, థమూద్ ప్రజల వార్త – వారికి రాలేదా? (أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ) 9:70; 14:9
- అల్లాహ్ పిలుపుకు నా సహాయకులు ఎవరు? హవారియూన్ (శిష్యులు) అన్నారు: "మేము అల్లాహ్ యొక్క సహాయకులం; మేము విశ్వసించాము." (مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا) 3:52; 61:14
- నీ ప్రభువు తన మార్గం నుండి ఎవరు తప్పిపోతారో బాగా ఎరిగినవాడు; మరియు సన్మార్గం పొందినవారు ఎవరో కూడా బాగా ఎరిగినవాడు. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 16:125; 68:7
- ఎందుకంటే, అల్లాహ్ సత్యం; ఇంకా, ఆయన కాకుండా వారు ప్రార్థించేవన్నీ అసత్యం. (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- ఎవరు అల్లాహ్కు, ఆయన ప్రవక్తకు విధేయత చూపుతాడో, ఆయన అతనిని స్వర్గాలలో ప్రవేశింపజేస్తాడు; వాటి క్రింద నదులు ప్రవహిస్తాయి. (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- నిశ్చయంగా, ఆయన మీకు చనిపోయిన జంతువును, రక్తాన్ని, పంది మాంసాన్ని, మరియు (ఇతరుల పేరుతో) చంపబడిన వాటిని నిషేధించాడు. (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- మీరు అల్లాహ్ ను తప్ప (ఎవరినీ) ఆరాధించకూడదు. నిశ్చయంగా, నేను మీకు ఒక దినం యొక్క శిక్షకు భయపడుతున్నాను. (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- అది అదృశ్య సమాచారాలలో ఒకటి, దానిని మేము నీకు దివ్యావిష్కృతిగా తెలియజేస్తున్నాము; నీవు వారి వద్ద లేవు, ఆ సమయంలో. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- మీ ప్రభువు నుండి మీలోని ఒక మనిషి ద్వారా మీకు హితబోధ వచ్చినందుకు మీరు ఆశ్చర్యపడుతున్నారా? (అతను) మిమ్మల్ని హెచ్చరించడానికి. (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- ఇలా చెప్పు: "నిశ్చయంగా, అల్లాహ్ను కాకుండా మీరు ప్రార్థించే వాటిని నేను ఆరాధించకుండా నిషేధించబడ్డాను." (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- తమ భార్యల విషయంలో లేదా వారి కుడిచేతులు సొంతం చేసుకున్న వారి విషయంలో తప్ప – నిశ్చయంగా వారు నిందించబడరు. (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- ఎందుకంటే, అల్లాహ్ రాత్రిని పగటిలో ప్రవేశింపజేస్తాడు; పగటిని రాత్రిలో ప్రవేశింపజేస్తాడు. (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- అగ్ని, అతను తన కుటుంబానికి ఇలా అన్నాడు: "ఉండండి; నేను ఒక అగ్నిని గమనించాను; బహుశా నేను దాని నుండి మీకు ఏదైనా తీసుకువస్తాను." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- అతను ఇలా అన్నాడు: "నేను అతని కంటే గొప్పవాడను; నీవు నన్ను అగ్నితో సృష్టించావు; అతన్ని మట్టితో సృష్టించావు." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- ఇంకా, వారికి "అల్లాహ్ అవతరింపజేసిన దాని వైపుకు మరియు ప్రవక్త వైపుకు రండి" అని చెప్పబడినప్పుడు, వారు అంటారు. (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- వారి కోసం నీవు దుఃఖించకు; వారు పన్నే కుట్రల గురించి నీవు సంకటంలో ఉండకు. (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- అల్లాహ్ నీకు ఏదైనా బాధ కలిగిస్తే, ఆయన తప్ప దానిని తొలగించేవాడు ఎవడూ లేడు; మరియు ఒకవేళ. (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- వారి పూర్వం తరాలు వారి నివాసాలలో సంచరించాయి. నిశ్చయంగా, అందులో సూచనలు ఉన్నాయి. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- ఇంకా, వారు అది అర్థం చేసుకోకుండా ఉండటానికి వారి హృదయాలపై తెరలను, వారి చెవులలో బరువును మేము ఉంచాము; మరియు (వారు విశ్వసించరు.) (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- వారి ప్రవక్తలు స్పష్టమైన సూచనలతో వచ్చారు; అయినా అల్లాహ్ వారిని అన్యాయం చేయలేదు; కానీ వారు తమకు తామే అన్యాయం చేసుకున్నారు. (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- మరియు భూమిపై, అల్లాహ్ కాకుండా మీకు ఎటువంటి సంరక్షకుడు లేదా సహాయకుడు లేరు. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- తరువాత, మీరు అదృశ్యమైన మరియు స్పష్టమైన వాటిని ఎరిగినవాని వైపు మరలించబడతారు; అప్పుడు ఆయన మీరు చేస్తున్నదాని గురించి మీకు తెలియజేస్తాడు. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- రాత్రి – మీరు అందులో విశ్రాంతి తీసుకోవడానికి; మరియు పగలు – (మీరు చూడటానికి) ప్రకాశవంతంగా. నిశ్చయంగా, అందులో ప్రజలకు సూచనలు ఉన్నాయి. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- ఇంకా, నీ ప్రభువు నుండి నీకు అవతరింపజేయబడినది వారిలో చాలా మందికి తిరుగుబాటు మరియు అవిశ్వాసాన్నే పెంచుతుంది. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- ఆయన ఇలా అన్నాడు: "నా ప్రజలారా! నేను నా ప్రభువు నుండి స్పష్టమైన ఆధారంపై ఉండి, ఆయన నాకు (ఇతరులు) ప్రసాదించినట్లయితే మీరు ఏమంటారు?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- ఇంకా, వారు ఇలా అంటారు: "ఆయన ప్రభువు నుండి ఆయనకు ఒక సూచన ఎందుకు అవతరింపజేయబడలేదు?" ఇలా చెప్పు: "నిశ్చయంగా." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
