- నీ ప్రభువు తన మార్గం నుండి ఎవరు తప్పిపోతారో బాగా ఎరిగినవాడు; మరియు ఆయనే బాగా ఎరిగినవాడు. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- మీరు అదృశ్యమైన మరియు స్పష్టమైన వాటిని ఎరిగినవాని వైపు మరలించబడతారు; అప్పుడు ఆయన మీరు చేస్తున్నదాని గురించి మీకు తెలియజేస్తాడు. (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- మీ కుమారులను చంపి, మీ స్త్రీలను బ్రతికి ఉంచారు; అందులో మీ ప్రభువు నుండి మీకు గొప్ప పరీక్ష ఉంది. (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- నిశ్చయంగా, నీ ప్రభువు తన మార్గం నుండి ఎవరు తప్పిపోతారో బాగా ఎరిగినవాడు; మరియు ఆయన. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- అల్లాహ్ – ఆయనకే ఆకాశాలలోనూ, భూమిలోనూ ఉన్న సమస్తం సొంతము. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- మీకు పూర్వం గతించిన సమాజాలలో – జిన్నులు మరియు మానవులలో. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- అల్లాహ్ను ఆరాధించండి; ఆయన తప్ప మీకు వేరే దైవం లేదు. మీరు భయపడరా? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- మరియు వారు అది అర్థం చేసుకోకుండా ఉండటానికి వారి హృదయాలపై తెరలను, వారి చెవులలో బరువును మేము ఉంచాము. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- పునరుత్థాన దినంలో, వారు విభేదిస్తూ ఉన్నదానిలో (ఆయన) వారి మధ్య తీర్పు చేస్తాడు. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- ఆయన ఇలా అన్నాడు: "నా ప్రజలారా! నేను నా ప్రభువు నుండి స్పష్టమైన ఆధారంపై ఉంటే మీరు ఏమంటారు?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّבِّي) 11:28; 11:63; 11:88
- అది మీ చేతులు ముందుగా పంపినదాని కారణంగా; మరియు అల్లాహ్ దాసులకు అన్యాయం చేయువాడు కాడు. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- ఇహలోకంలో వారికి అవమానం, పరలోకంలో మహా శిక్ష ఉంది. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- ఆకాశాలలో ఉన్నవి, భూమిలో ఉన్నవి; అల్లాహ్ సరిపోయే సంరక్షకుడు. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- ఎవరు విశ్వసించి సత్కర్మలు చేశారో వారు తప్ప; వారికి అంతంలేని ప్రతిఫలం ఉంది. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- నీవు నాకు భాగస్వామిని కల్పించడం కోసం – నీకు దాని గురించి ఏ జ్ఞానమూ లేదు; కాబట్టి వారిద్దరికీ నీవు విధేయత చూపకు. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- నిశ్చయంగా, ఇది ఒక హితబోధ; కాబట్టి కోరినవాడు తన ప్రభువు వైపు ఒక మార్గాన్ని ఎంచుకుంటాడు. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- ఇంకా, ఎవరు కృతజ్ఞత చూపుతాడో, అతను తన కోసమే కృతజ్ఞత చూపుతాడు; ఎవరు నిరాకరిస్తాడో – నిశ్చయంగా. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- ఎవరు నమాజును స్థాపిస్తారో, జకాత్ ఇస్తారో, మరియు పరలోకాన్ని నమ్ముతారో. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ఇబ్రాహీం, ఇస్మాయీల్, ఇస్హాక్, యాకూబ్, మరియు వంశాలు; మరియు మూసా మరియు ఈసాలకు ప్రసాదించబడినవి. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- గుంపులుగా, వారు దాని వద్దకు వచ్చే వరకు; దాని ద్వారాలు తెరవబడతాయి; దాని కాపలాదారులు వారితో అంటారు. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- అల్లాహ్ మీ ప్రమాణాలలోని పనికిమాలిన దానికి మిమ్మల్ని పట్టుకోడు; కానీ, దేనికి (మిమ్మల్ని పట్టుకుంటాడు?) (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- (అల్లాహ్) కరుణ – వారు దానితో సంతోషించారు; ఇంకా, వారి చేతులు ముందుగా పంపిన కారణంగా ఏదైనా చెడు వారిని తాకినట్లయితే. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- వాటి క్రింద నదులు ప్రవహిస్తాయి; అందులో వారు శాశ్వతంగా ఉంటారు; ఇంత అద్భుతమైన ప్రతిఫలం కార్మికులకు! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- అల్లాహ్ ఆకాశాలలోనూ, భూమిపైనా ఉన్నదాన్ని ఎరుగును; మరియు అల్లాహ్. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- అల్లాహ్ కు విధేయత చూపండి; ప్రవక్తకు కూడా విధేయత చూపండి; మీరు మరలితే, ఆయనపై (కట్టు). (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- వారికి వారి ప్రతిఫలం వారి ప్రభువు వద్ద ఉంది; వారికి భయం లేదు; మరియు వారు. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- ఇంకా, వారు ఇలా అన్నారు: "మేము ఎముకలుగా, ధూళిగా మారినప్పుడు, మేము క్రొత్త సృష్టిగా లేపబడతామా?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- మరియు అల్లాహ్ కాకుండా వారు తమకు ఎటువంటి సంరక్షకుడిని లేదా సహాయకుడిని కనుగొనలేరు. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- నీవు ఎంతకాలం (అక్కడ) ఉన్నావు? అతను ఇలా అన్నాడు: "నేను ఒక రోజు లేదా ఒక రోజులో కొంత భాగం ఉన్నాను." అతను ఇలా అన్నాడు: (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- శాశ్వతంగా – పునరుత్థాన దినం వరకు. అల్లాహ్ తప్ప ఏ దైవం మీకు (ఇది) తీసుకువస్తాడు? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- ఎవరు సత్కర్మ చేస్తాడో – అతను పురుషుడైనా లేదా స్త్రీ అయినా – మరియు విశ్వాసి అయినట్లయితే. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- ఎవరు అల్లాహ్ మార్గం నుండి నిరోధిస్తారో, దానిని వంకరగా చేయాలని కోరుతారో, మరియు పరలోకాన్ని నమ్మరో. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- మీరు కోరుకున్న చోట (తినండి); ఈ చెట్టు దగ్గరకు వెళ్లవద్దు; (అలా చేస్తే) మీరు అన్యాయకారులలో అవుతారు. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- ఇలా చెప్పు: "నా ప్రజలారా! మీ స్థితిలో పనిచేయండి; నేను (నా స్థితిలో) పనిచేస్తాను; అప్పుడు మీరు తెలుసుకుంటారు." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- నిశ్చయంగా, నష్టపోయినవారు ఎవరంటే, పునరుత్థాన దినంలో తమను తాము మరియు తమ కుటుంబాలను నష్టపరచుకున్నవారే. వినండి! (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- ఎవరు సన్మార్గం పొందుతాడో, అతను తన కోసమే సన్మార్గం పొందుతాడు; ఎవరు తప్పిపోతాడో, అతను తనకు వ్యతిరేకంగానే తప్పిపోతాడు; మరియు ఎవరూ. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- మరియు తిరస్కరించినవారు ఇలా అంటారు: "ఆయన ప్రభువు నుండి ఆయనకు ఒక సూచన ఎందుకు అవతరింపజేయబడలేదు?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- ఆయనే మీకు రాత్రిని (విశ్రాంతి కోసం) ఏర్పరిచాడు; మరియు పగలును (చూడటానికి) ప్రకాశవంతంగా. నిశ్చయంగా. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- ఏ వ్యాపారమూ లేని, ఏ (స్నేహము) లేని రోజు రాకముందు. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- వారు ఆలోచించటానికి; వారి సహచరునికి పిచ్చి లేదు; అతను ఒక హెచ్చరిక చేసేవాడు మాత్రమే. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- అందులో వారు శాశ్వతంగా ఉంటారు; శిక్ష వారికి తేలికపరచబడదు; మరియు వారికి వాయిదా కూడా ఇవ్వబడదు. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- మేము వారిలో కొందరికి అనుభవించటానికి ఇచ్చిన దాని వైపు నీ కళ్ళను చాచకు. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- మరియు ప్రజలకు వారి వస్తువులలో మోసం చేయవద్దు; భూమిలో అల్లకల్లోలం సృష్టించకండి. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- మరియు ఆయన జన్మించిన రోజు, ఆయన మరణించే రోజు, మరియు ఆయన బ్రతికి లేపబడే రోజు – శాంతి ఉంటుంది. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- నా ప్రజలారా! మీ స్థితిలో పనిచేయండి; నేను (నా స్థితిలో) పనిచేస్తాను; అప్పుడు మీరు తెలుసుకుంటారు – ఎవరు. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- అల్లాహ్ అనుమతి లేకుండా ఏ ప్రవక్త కూడా ఒక సూచనను తీసుకురాలేడు. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- తరువాత, ప్రతి ఆత్మకు తను సంపాదించినదానికి పూర్తిగా ప్రతిఫలం ఇవ్వబడుతుంది; మరియు వారికి అన్యాయం చేయబడదు. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- పురుషుడైనా, స్త్రీ అయినా, మరియు విశ్వాసి అయినట్లయితే – అటువంటి వారు స్వర్గంలో ప్రవేశిస్తారు. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- ఆయన ఎటువంటి సంతానాన్ని తీసుకోలేదు; మరియు ఆయన పరిపాలనలో ఎటువంటి భాగస్వామి లేడు. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- అల్లాహ్ ఎవరికి సన్మార్గం చూపిస్తాడో, అతను సన్మార్గం పొందినవాడు; ఎవరిని ఆయన తప్పుదారి పట్టిస్తాడో, వారికి నీవు ఎటువంటి సంరక్షకుడిని కనుగొనలేవు. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- ఇదిగో చూడు! వారు నీకు ఎలా ఉదాహరణలు ఇస్తున్నారు; వారు తప్పిపోయారు; మరియు (సరైన) మార్గం కనుగొనలేరు. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- ఇలా చెప్పు: "నేను నా ప్రభువుకు విధేయత చూపకపోతే, ఒక మహా దినం యొక్క శిక్షకు భయపడుతున్నాను." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- వారిద్దరి గుప్తావయవాలు వారికి ప్రత్యక్షమయ్యాయి; వారు స్వర్గపు ఆకులను తమపై కప్పుకోవడం మొదలు పెట్టారు. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- మరియు, మీరు సత్యవంతులు అయితే, అల్లాహ్ కాకుండా మీరు శక్తి కలిగిన వారిని పిలవండి. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- భూమిలోని సమస్తమూ, మరియు దానితో పాటు అంతే (మరొక మడత) – దానితో (తమను) విముక్తి చేసుకోవటానికి. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- మేము మీకు ప్రసాదించిన దాన్ని గట్టిగా పట్టుకోండి; అందులో ఉన్నదాన్ని గుర్తుచేసుకోండి – మీరు భయపడి ప్రవర్తించవచ్చు. (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- ప్రపంచవాసులలో మీకు పూర్వం ఎవరూ చేయని అశ్లీలతను మీరు చేస్తున్నారా? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- అల్లాహ్ కు ఆకాశాలలోనూ, భూమిలోనూ ఉన్నదంతా చెందుతుంది; మరియు అల్లాహ్ (అన్నిటినీ) కలిగినవాడు. (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- వారు చేసిన చెడుల ఫలితం వారికి ఎదురైంది; మరియు వారు ఎగతాళి చేస్తున్నది వారిని చుట్టుముట్టింది. (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- మీలో నుండే (వచ్చిన) ఒక ప్రవక్త; ఆయన మీకు మా సూచనలను వినిపిస్తాడు; మిమ్మల్ని శుద్ధి చేస్తాడు; మరియు మీకు గ్రంథాన్ని మరియు వివేకాన్ని బోధిస్తాడు. (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- దాని నుండి పన్నెండు ఊటలు (ప్రవహించాయి); ప్రతి సమూహం తమ నీటి స్థానాన్ని తెలుసుకుంది. (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- ఊహను తప్ప (వేరే లేదు); నిశ్చయంగా, ఊహ సత్యం ఎదుట ఎటువంటి ప్రయోజనం ఇవ్వదు. (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- నేను అతనిని సమంగా చేసి, అతనిలో నా ఆత్మ నుండి ఊదినప్పుడు, మీరు అతనికి సాష్టాంగపడి పడండి. (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- (పరలోక) నివాసం యొక్క ముగింపు ఎవరికి? నిశ్చయంగా, అన్యాయకారులు విజయం సాధించరు. (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- ఎవరు ఆకాశాలను మరియు భూమిని సృష్టించాడో, ఆయన వారి వంటి వారిని సృష్టించగల సమర్థుడు. (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- విశ్వసించిన పురుషులకు మరియు విశ్వసించిన స్త్రీలకు – స్వర్గాలు, వాటి క్రింద నదులు ప్రవహిస్తాయి; అందులో వారు శాశ్వతంగా ఉంటారు. (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
- మరియు నీవు వారిని "ఆకాశాలను మరియు భూమిని సృష్టించినవాడు ఎవరు?" అని అడిగితే, వారు "అల్లాహ్" అని చెప్పాలి. ఇలా చెప్పు: (وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلِ) 31:25; 39:38
- ఈ ఖుర్ఆన్లో మేము ప్రజలకు ప్రతి రకమైన ఉదాహరణను పొందుపరిచాము. (وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ) 30:58; 39:27
- మా ప్రవక్తలు లూత్ వద్దకు వచ్చినప్పుడు, ఆయన వారి వల్ల బాధపడ్డారు; మరియు ఇబ్బంది పడ్డారు; మరియు ఇలా అన్నారు. (جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ) 11:77; 29:33
- మరియు మేము దేవదూతలతో: "ఆదమ్ కు సాష్టాంగపడండి" అని చెప్పినప్పుడు; ఇబ్లీస్ తప్ప వారు సాష్టాంగపడ్డారు; అతను తిరస్కరించాడు. (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَى) 2:34; 20:116
- మరియు భూమిని మేము విస్తరించాము; దానిపై స్థిరమైన పర్వతాలను నిలిపాము; దానిలో ప్రతి రకమైన (పంటలను) మొలపించాము. (وَالْأَرْضَ مَدَدْنَاهَا وَأَلْقَيْنَا فِيهَا رَوَاسِيَ وَأَنبَتْنَا فِيهَا مِن كُلِّ) 15:19; 50:7
- వారు తమ ధర్మాన్ని ఆయనకు పవిత్రం చేస్తూ అల్లాహ్ వైపు ప్రార్థించారు; ఆయన వారిని (సముద్రం నుండి) భూమి (ఒడ్డు) కు రక్షించినప్పుడు. (دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ) 29:65; 31:32
- వారికి మరిగే నీటి పానీయం మరియు బాధాకరమైన శిక్ష ఉంది – వారు తిరస్కరిస్తున్న కారణంగా. (لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْفُرُونَ) 6:70; 10:4
- మేము అల్లాహ్ ను కాకుండా, మాకు ప్రయోజనం కానీ, హాని కానీ చేయని వాటిని ప్రార్థిస్తామా? (أَنَدْعُو مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106
- నిశ్చయంగా, అల్లాహ్ ఆకాశాలలో ఉన్నదాన్ని, భూమిలో ఉన్నదాన్ని ఎరుగును. (أَنَّ اللَّهَ يَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 5:97; 58:7
""";
